const LOGO="data:image/png;base64,";
const IMG={worker:"data:image/jpeg;base64,",student:"data:image/jpeg;base64,",admin:"data:image/jpeg;base64,"};
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=t=>new Date(t).toLocaleString([],{dateStyle:'medium',timeStyle:'short'});
const H=36e5,D=24*H,now=Date.now();
const CATS=['Electrical','Plumbing','Furniture','Fan / Light','Classroom','Other'];
const WORKERS=['Ravi (Electrician)','Meena (Plumber)','Karthik (Carpenter)','Suresh (General)'];
const WORKER_PWS={'Ravi (Electrician)':'ravi123','Meena (Plumber)':'meena123','Karthik (Carpenter)':'karthik123','Suresh (General)':'suresh123'};
const mk=(id,by,cat,desc,loc,prio,status,age,extra={})=>({id,by,cat,desc,loc,sugg:prio,prio,status,worker:null,before:null,after:null,remarks:'',votes:[],link:null,times:[['Reported',now-age]],...extra});
let issues=[];
async function loadIssues() {
    try {
        const res = await fetch('http://localhost:3000/api/issues');
        const data = await res.json();
        issues = data.map(d => ({...d, by: d.by_user, before: d.before_photo, after: d.after_photo}));
        render();
    } catch(e) { console.error(e); }
}
loadIssues();
const S={role:null,user:'You',view:'login',sel:null,f:{q:'',cat:'',st:'',pr:''},nid:200};
let accounts=[{role:'admin',id:'admin01',pw:'admin123'}];
try{const saved=localStorage.getItem('samats_data');if(saved){const o=JSON.parse(saved);issues=o.issues;Object.assign(S,o.S);if(o.accounts)accounts=o.accounts;}}catch(e){}
const NAVS={worker:[['tasks','My tasks'],['stats','Statistics']],student:[['report','Report issue'],['mine','My complaints'],['board','All issues'],['stats','Statistics']],admin:[['admin','Dashboard'],['stats','Statistics']]};
const PR={High:0,Medium:1,Low:2};

function theme(){const r=document.documentElement,l=r.dataset.theme=='dark';r.dataset.theme=l?'light':'dark';$('#tbtn').textContent=l?'🌙 Dark':'☀ Light'}
function toast(m,e){const t=document.createElement('div');t.className='toast'+(e?' err':'');t.textContent=m;document.body.append(t);setTimeout(()=>t.remove(),2600)}
function go(v,id){S.view=v;if(id!=null)S.sel=id;render();scrollTo(0,0)}
const HOME={student:'report',admin:'admin',worker:'tasks'};
const RL={student:['🎓','Student / Staff login','Report problems and track repairs.','Roll no. / Staff ID','e.g. 22CS104'],admin:['🛡','Admin login','Prioritize, assign and verify repairs.','Admin ID','e.g. admin01'],worker:['🔧','Maintenance worker login','See your assigned jobs and upload repair proof.']};
function home(){go(S.role?HOME[S.role]:'login')}
function pick(r){S.lr=r;go('lg')}
function doLogin(){const r=S.lr,id=$('#li').value.trim(),pw=$('#lp').value;
 if(!id)return toast('Enter your '+(r=='worker'?'name':'ID'),1);
 if(!pw)return toast('Enter your password',1);
 if(r=='worker'){if(pw!=WORKER_PWS[id])return toast('Incorrect password',1);}
 else{const acc=accounts.find(a=>a.id==id&&a.role==r);if(!acc)return toast('Account not found. Please create one.',1);if(acc.pw!=pw)return toast('Incorrect password',1);}
 S.role=r;S.name=id;S.user=r=='worker'?id:(r=='admin'?'Admin':'You');toast('Welcome, '+id.split(' (')[0]);go(HOME[r])}
function doSignup(){const r=S.lr,id=$('#li').value.trim(),pw=$('#lp').value;
 if(!id)return toast('Enter your '+(r=='worker'?'name':'ID'),1);
 if(!pw)return toast('Enter your password',1);
 if(accounts.find(a=>a.id==id&&a.role==r))return toast('Account already exists',1);
 accounts.push({role:r,id,pw});toast('Account created');doLogin()}
function lgV(){const r=S.lr,c=RL[r];
 return `<div class="lgbox" onkeydown="if(event.key=='Enter')doLogin()"><div class="hero"><img src="${LOGO}" alt="College logo"><div><h1 style="margin:0">FixIt</h1></div></div>
<div class="card bgi fm" style="--img:url(${IMG[r]})"><h2 style="color:var(--ac)">${c[1]}</h2><p class="sub" style="margin-bottom:6px">${c[2]}</p>
${r=='worker'?`<label>Your name</label><select id="li">${WORKERS.map(w=>`<option>${w}</option>`).join('')}</select>`:`<label>${c[3]}</label><input id="li" placeholder="${c[4]}" autocomplete="off">`}
<label>Password</label><input id="lp" type="password" placeholder="Enter password">
<div class="row2" style="margin-top:18px"><button class="btn" onclick="doLogin()">Log in</button>${r!='worker'?`<button class="btn ghost" onclick="doSignup()">Create account</button>`:''}<button class="btn ghost" onclick="go('login')">Back</button></div></div></div>`}
function tasksV(){const m=issues.filter(i=>i.worker==S.user).sort((a,b)=>PR[a.prio]-PR[b.prio]),c=s=>m.filter(i=>i.status==s).length;
 return `<h1>My tasks</h1><p class="sub">Jobs assigned to ${esc(S.user)}. Urgent ones first.</p><div class="grid g4" style="margin-bottom:16px">${[['Assigned to me',m.length],['In progress',c('In Progress')],['Resolved',c('Resolved')]].map(x=>`<div class="card stat"><b>${x[1]}</b><span>${x[0]}</span></div>`).join('')}</div><div class="card">${listRows(m)}</div>`}
function logout(){S.role=null;go('login')}
const pill=p=>`<span class="pill ${p}">${p}</span>`;
const stp=s=>`<span class="pill st-${s}">${s}</span>`;
const get=id=>issues.find(i=>i.id==id);

/* smart features */
function suggest(t){t=t.toLowerCase();
 if(/wire|electr|spark|shock|switchboard|socket|short.?circuit|fire|smoke|gas|flood|glass|exposed|danger|collapse|near the (wire|switch)/.test(t))return 'High';
 if(/fan|light|ac\b|projector|door|window|lock|not (working|rotating)|leak|drip|bench|chair|broken/.test(t))return 'Medium';
 return t.trim()?'Low':null}
function dups(loc,cat,desc){const w=x=>new Set(x.toLowerCase().split(/\W+/).filter(a=>a.length>3));const dw=w(desc);
 return issues.filter(i=>i.status!='Resolved'&&!i.link&&i.cat==cat&&(i.loc.toLowerCase()==loc.trim().toLowerCase()||[...w(i.desc)].filter(a=>dw.has(a)).length>=2)).slice(0,3)}


/* views */
function loginV(){const card=(r,i,t,d)=>`<div class="card role bgi" style="--img:url(${IMG[r]})" onclick="pick('${r}')" tabindex="0" onkeydown="if(event.key=='Enter')pick('${r}')"><h2>${t}</h2><p class="sub">${d}</p><span class="btn">Log in</span></div>`;
 return `<div class="hero"><img src="${LOGO}" alt="College logo"><div><h1 style="margin:0">FixIt</h1><p class="sub" style="margin:4px 0 0">Report it. Track it. See it fixed.</p></div></div>
<div class="grid g4" style="grid-template-columns:repeat(auto-fit,minmax(230px,1fr))">${card('student','🎓','Student / Staff','Report problems and follow their progress.')}${card('admin','🛡','Admin','Prioritize, assign and verify repairs.')}${card('worker','🔧','Maintenance worker','See assigned jobs and upload repair proof.')}</div>`}

function reportV(){return `<h1>Report an issue</h1><p class="sub">Add where it is and what's wrong. FixIt checks priority and duplicates for you.</p>
<div class="grid g2"><div class="card">
<label>Category</label><select id="rc" onchange="chk()">${CATS.map(c=>`<option>${c}</option>`).join('')}</select>
<label>Location / room</label><input id="rl" placeholder="e.g. Block A – Room 204" oninput="chk()">
<label>Description</label><textarea id="rd" placeholder="What is wrong?" oninput="chk()"></textarea>
<label>Before photo (optional)</label><input type="file" id="rp" accept="image/*">
<div class="row2" style="margin-top:16px"><button class="btn" onclick="submitIssue()">Submit report</button></div></div>
<div><div class="card"><h2>Smart priority</h2><div id="sp" class="sub">Start typing the description to see a suggested priority.</div></div>
<div id="dp"></div></div></div>`}
function chk(){const d=$('#rd').value,p=suggest(d);
 $('#sp').innerHTML=p?`Suggested priority: ${pill(p)}<br><small class="sub">${p=='High'?'Possible safety risk detected. Admin may adjust.':'Based on keywords in your description.'}</small>`:'Start typing the description to see a suggested priority.';
 const x=($('#rl').value&&d.length>8)?dups($('#rl').value,$('#rc').value,d):[];
 $('#dp').innerHTML=x.length?`<div class="warn"><b>Possible duplicates</b><p class="sub" style="margin:4px 0 8px">Already reported? Support it instead of creating a new ticket.</p>${x.map(i=>`<div class="row2" style="justify-content:space-between;margin:6px 0"><span>#${i.id} ${esc(i.desc)}<br><small class="sub">${esc(i.loc)} · ${i.votes.length+1} affected</small></span><button class="btn sm" onclick="support(${i.id})">I have this issue too</button></div>`).join('')}</div>`:''}
function submitIssue(){const loc=$('#rl').value.trim(),desc=$('#rd').value.trim();
 if(!loc||!desc)return toast('Add a location and description',1);
 const f=$('#rp').files[0],add=async b=>{const p=suggest(desc)||'Low',d=dups(loc,$('#rc').value,desc);
  const dupOf = d.length ? d[0].id : null;
  const payload = { by_user: S.user, cat: $('#rc').value, desc, loc, prio: p, sugg: p, status: 'Pending', dupOf, before_photo: b };
  const res = await fetch('http://localhost:3000/api/issues', { method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify(payload) });
  const data = await res.json();
  toast('Issue reported');
  await loadIssues();
  go('detail', data.id);
 };
 if(f){const r=new FileReader();r.onload=()=>add(r.result);r.readAsDataURL(f)}else add(null)}

function listRows(a,adm){return a.length?`<div class="tw"><table><tr><th>ID</th><th>Issue</th><th>Location</th><th>Priority</th><th>Status</th><th>Affected</th><th>Date</th></tr>${a.map(i=>`<tr class="row" onclick="go('detail',${i.id})"><td>#${i.id}</td><td>${esc(i.cat)}<br><small class="sub">${esc(i.desc.slice(0,60))}</small></td><td>${esc(i.loc)}</td><td>${pill(i.prio)}</td><td>${stp(i.status)}</td><td>${i.votes.length+1}</td><td>${fmt(i.times[0][1])}</td></tr>`).join('')}</table></div>`:`<p class="sub">Nothing here yet. Report an issue to get started.</p>`}
function mineV(){return `<h1>My complaints</h1><p class="sub">Everything you reported, with live status.</p><div class="card">${listRows(issues.filter(i=>i.by==S.user))}</div>`}
function filt(){const f=S.f,q=f.q.toLowerCase();return issues.filter(i=>(!q||(i.desc+i.loc+i.cat).toLowerCase().includes(q))&&(!f.cat||i.cat==f.cat)&&(!f.st||i.status==f.st)&&(!f.pr||i.prio==f.pr)).sort((a,b)=>PR[a.prio]-PR[b.prio]||b.times[0][1]-a.times[0][1])}
function filtBar(){const o=(a,v,l)=>`<option value="">${l}</option>`+a.map(x=>`<option ${v==x?'selected':''}>${x}</option>`).join('');
 return `<div class="filters"><input placeholder="Search location or keyword" value="${esc(S.f.q)}" oninput="S.f.q=this.value;tbl()"><select onchange="S.f.cat=this.value;tbl()">${o(CATS,S.f.cat,'All categories')}</select><select onchange="S.f.st=this.value;tbl()">${o(['Pending','In Progress','Resolved'],S.f.st,'All statuses')}</select><select onchange="S.f.pr=this.value;tbl()">${o(['High','Medium','Low'],S.f.pr,'All priorities')}</select></div>`}
function tbl(){$('#tb').innerHTML=listRows(filt())}
function cnt(){const c=s=>issues.filter(i=>i.status==s).length;return{t:issues.length,p:c('Pending'),ip:c('In Progress'),r:c('Resolved')}}
function cards(){const c=cnt();return `<div class="grid g4" style="margin-bottom:16px">${[['Total',c.t],['Pending',c.p],['In progress',c.ip],['Resolved',c.r],['High priority',issues.filter(i=>i.prio=='High'&&i.status!='Resolved').length]].map(x=>`<div class="card stat"><b>${x[1]}</b><span>${x[0]}</span></div>`).join('')}</div>`}
function boardV(){return `<h1>All issues</h1><p class="sub">Check if your problem is already reported and support it.</p>${filtBar()}<div class="card" id="tb">${listRows(filt())}</div>`}
function adminV(){return `<h1>Admin dashboard</h1><p class="sub">Urgent problems appear first.</p>${cards()}${filtBar()}<div class="card" id="tb">${listRows(filt())}</div>`}

function detailV(){const i=get(S.sel),adm=S.role=='admin',wk=S.role=='worker',steps=['Reported','Assigned','In Progress','Resolved'];
 const tm=Object.fromEntries(i.times);
 const img=(s,l)=>`<div><small class="sub">${l}</small><div class="ph" ${s&&s!='x'?`style="background-image:url(${s})"`:''}>${s?(s=='x'?'Repair photo (demo)':''):'No photo'}</div></div>`;
 return `<p><button class="btn ghost sm" onclick="go(S.role=='student'?'mine':HOME[S.role])">← Back</button></p>
<div class="row2"><h1 style="margin:0">#${i.id} ${esc(i.cat)}</h1>${pill(i.prio)} ${stp(i.status)}</div>
<p class="sub">${esc(i.loc)} · reported by ${esc(i.by)} · ${i.votes.length+1} affected${i.worker?` · ${esc(i.worker)}`:''}</p>
${i.dupOf?`<div class="warn">Possible duplicate of <a href="#" onclick="go('detail',${i.dupOf});return false" style="color:var(--ac)">#${i.dupOf}</a>.${adm?` <button class="btn sm" onclick="merge(${i.id})">Link &amp; merge</button>`:''}</div>`:''}
${i.link?`<div class="warn">Merged into #${i.link}.</div>`:''}
<div class="grid g2" style="margin-top:14px"><div class="card"><h2>Description</h2><p>${esc(i.desc)}</p>
<p class="sub">Suggested priority: ${pill(i.sugg)}</p>
${i.remarks?`<p><b>Resolution remarks:</b> ${esc(i.remarks)}</p>`:''}
${S.role=='student'&&i.status!='Resolved'?`<button class="btn" onclick="support(${i.id})">I have this issue too</button>`:''}
<div class="grid g2" style="margin-top:14px">${img(i.before,'Before')}${img(i.after,'After')}</div></div>
<div><div class="card"><h2>Live timeline</h2><ul class="tl">${steps.map(s=>`<li class="${tm[s]?'done':''}">${s}<small>${tm[s]?fmt(tm[s]):'Waiting'}</small></li>`).join('')}</ul></div>
${adm&&i.status!='Resolved'?`<div class="card" style="margin-top:14px"><h2>Maintenance actions</h2>
<label>Final priority</label><select onchange="upd(${i.id},'prio',this.value)">${['High','Medium','Low'].map(p=>`<option ${i.prio==p?'selected':''}>${p}</option>`).join('')}</select>
<label>Assign worker</label><select onchange="assign(${i.id},this.value)"><option value="">Unassigned</option>${WORKERS.map(w=>`<option ${i.worker==w?'selected':''}>${w}</option>`).join('')}</select>
<div class="row2" style="margin-top:12px"><button class="btn ghost sm" onclick="prog(${i.id})">Mark In Progress</button></div>
<label>After-repair photo (required to resolve)</label><input type="file" id="ap" accept="image/*">
<label>Resolution remarks</label><input id="rm" placeholder="What was fixed?">
<button class="btn" style="margin-top:12px" onclick="resolve(${i.id})">Mark Resolved</button></div>`:''}${wk&&i.worker==S.user&&i.status!='Resolved'?`<div class="card" style="margin-top:14px"><h2>Your job</h2><button class="btn ghost sm" onclick="prog(${i.id})">Start work (In Progress)</button>
<label>After-repair photo (required to resolve)</label><input type="file" id="ap" accept="image/*">
<label>Resolution remarks</label><input id="rm" placeholder="What was fixed?">
<button class="btn" style="margin-top:12px" onclick="resolve(${i.id})">Mark Resolved</button></div>`:''}</div></div>`}







function statsV(){const c=cnt(),rate=c.t?Math.round(c.r/c.t*100):0;
 const grp=k=>{const m={};issues.forEach(i=>m[i[k]]=(m[i[k]]||0)+1);return m};
 const bars=m=>{const mx=Math.max(...Object.values(m));return Object.entries(m).map(([k,v])=>`<div class="bar"><span>${esc(k)}</span><i style="width:${v/mx*55}%"></i><b>${v}</b></div>`).join('')};
 const rs=issues.filter(i=>i.status=='Resolved'),avg=rs.length?Math.round(rs.reduce((a,i)=>a+(i.times.at(-1)[1]-i.times[0][1]),0)/rs.length/H):null;
 return `<h1>Statistics</h1><p class="sub">The campus maintenance picture right now.</p>${cards()}
<div class="grid g2"><div class="card"><h2>Resolution rate</h2><div class="ring" style="background:conic-gradient(var(--ac) ${rate*3.6}deg,var(--card2) 0)"><div>${rate}%</div></div>
<p class="sub" style="text-align:center">${avg!=null?`Average resolution time: ${avg} hours`:'No resolved issues yet'}</p></div>
<div class="card"><h2>By status</h2>${bars({Pending:c.p,'In Progress':c.ip,Resolved:c.r})}</div>
<div class="card"><h2>By category</h2>${bars(grp('cat'))}</div>
<div class="card"><h2>By location</h2>${bars(grp('loc'))}</div></div>`}

function render(){
 try{localStorage.setItem('samats_data',JSON.stringify({issues,S,accounts}));}catch(e){}
 const nv=S.role?NAVS[S.role]:[];
 $('#nav').innerHTML=nv.map(n=>`<button class="${S.view==n[0]?'on':''}" onclick="go('${n[0]}')">${n[1]}</button>`).join('');
 $('#out').hidden=!S.role;
 if(!S.role&&S.view!='lg')S.view='login';
 const V={lg:lgV,tasks:tasksV,login:loginV,report:reportV,mine:mineV,board:boardV,admin:adminV,stats:statsV,detail:detailV};
 $('#app').innerHTML=V[S.view]()}
$('#hl').src=LOGO;
render();
async function apiUpd(id, payload) {
    try {
        await fetch(`http://localhost:3000/api/issues/${id}`, { method: 'PUT', headers: {'Content-Type': 'application/json'}, body: JSON.stringify(payload) });
        await loadIssues();
    } catch(e) {}
}

function upd(id,k,v){get(id)[k]=v;toast('Priority updated');render(); apiUpd(id, {[k]: v});}
function stamp(i,s){if(!i.times.find(t=>t[0]==s))i.times.push([s,Date.now()])}
function assign(id,w){const i=get(id);if(!w)return;i.worker=w;stamp(i,'Assigned');toast('Assigned to '+w);render(); apiUpd(id, {worker: w, times: i.times});}
function prog(id){const i=get(id);if(!i.worker)return toast('Assign a worker first',1);stamp(i,'In Progress');i.status='In Progress';toast('Status: In Progress');render(); apiUpd(id, {status: 'In Progress', times: i.times});}
function merge(id){const i=get(id),m=get(i.dupOf);m.votes.push(...i.votes,i.by);i.link=m.id;i.dupOf=null;toast('Linked to #'+m.id);render(); apiUpd(i.id, {link: m.id, dupOf: null}); apiUpd(m.id, {votes: m.votes});}
function resolve(id){const i=get(id),f=$('#ap').files[0];
 if(!f)return toast('Upload an after-repair photo first',1);
 if(!i.worker)return toast('Assign a worker first',1);
 const r=new FileReader();r.onload=()=>{i.after=r.result;i.remarks=$('#rm').value;stamp(i,'In Progress');stamp(i,'Resolved');i.status='Resolved';toast('Issue resolved with proof');render(); apiUpd(id, {after_photo: r.result, remarks: i.remarks, status: 'Resolved', times: i.times});}; r.readAsDataURL(f);}
function support(id){const i=get(id);if(i.votes.includes(S.user)||i.by==S.user)return toast('You already support this issue',1);i.votes.push(S.user);toast('Added: you have this issue too');render(); apiUpd(id, {votes: i.votes});}
